export function getBranchesForGroup(groupName) {
  const grp = String(groupName || '').toUpperCase();
  if (grp.includes('GEELY') || grp === 'GALAXY' || grp === 'RIDDARA') {
    return GEELY_BRANCHES;
  }
  return BMW_BRANCHES;
}
